    """Return True if `colors` follows the same pattern as `patterns`.

    Each pattern label must map to exactly one color, and each color must
    map back to exactly one pattern label (a one-to-one correspondence).
    """
    if len(colors) != len(patterns):
        return False

    pattern_to_color = {}
    color_to_pattern = {}
    for color, pattern in zip(colors, patterns):
        if pattern in pattern_to_color:
            if pattern_to_color[pattern] != color:
                return False
        else:
            pattern_to_color[pattern] = color

        if color in color_to_pattern:
            if color_to_pattern[color] != pattern:
                return False
        else:
            color_to_pattern[color] = pattern

    return True


